<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$payments=$db->query("SELECT ip.*,i.invoice_number,l.name client_name FROM invoice_payments ip JOIN invoices i ON i.id=ip.invoice_id JOIN leads l ON l.id=ip.lead_id ORDER BY ip.created_at DESC")->fetchAll();$stats=$db->query("SELECT COUNT(*) total,COALESCE(SUM(CASE WHEN status='successful' THEN amount ELSE 0 END),0) successful,COALESCE(SUM(CASE WHEN status='pending' THEN amount ELSE 0 END),0) pending,COALESCE(SUM(CASE WHEN status='failed' THEN amount ELSE 0 END),0) failed FROM invoice_payments")->fetch();function pm($v,$c){return $c.' '.number_format((float)$v,2);} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment Operations</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><h1 class="h2">Payment Operations</h1><p class="text-muted">Transactions, reconciliation and payment history.</p><div class="row g-3 mb-4"><div class="col-md-3"><div class="card"><div class="card-body"><small>Total Transactions</small><h3><?=$e($stats['total'])?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Successful</small><h3><?=pm($stats['successful'],'NGN')?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Pending</small><h3><?=pm($stats['pending'],'NGN')?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Failed</small><h3><?=pm($stats['failed'],'NGN')?></h3></div></div></div></div><div class="card shadow-sm border-0"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Reference</th><th>Invoice</th><th>Client</th><th>Amount</th><th>Gateway</th><th>Status</th><th>Paid At</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=$e($p['reference'])?></td><td><?=$e($p['invoice_number'])?></td><td><?=$e($p['client_name'])?></td><td><?=pm($p['amount'],$p['currency'])?></td><td><?=$e($p['gateway'])?></td><td><span class="badge text-bg-<?= $p['status']==='successful'?'success':($p['status']==='failed'?'danger':'warning')?>"><?=$e($p['status'])?></span></td><td><?=$e($p['paid_at']?:'—')?></td></tr><?php endforeach;?><?php if(!$payments):?><tr><td colspan="7" class="p-4 text-muted">No payment transactions yet.</td></tr><?php endif;?></tbody></table></div></div></main></body></html>